('awin-embossed-graphics-family-organize-by-day-super-slab-white-117001-41721851768','Embossed Graphics','toys-hobbies','party-supplies','https://www.embossedgraphics.com/common/images/2015_item_images/801/ssw103-801.jpg','["Family Organize by Day Super Slab - White","35.95","USD","Embossed Graphics","Gifts","https://www.awin1.com/pclick.php?p=41721851768&a=2893129&m=117001","The Family Organize By Day Super Slab will help you coordinate your family''s activities with ease. Clearly organize your family''s sports activities, doctor appointments and PTO meetings. You may even find time for a family dinner. Now if you could just clone yourself to be two places at once... Personalize this item with family names, choice of lettering style and ink color."]'),
('awin-embossed-graphics-family-personalized-candle-engraved-117001-41721850485','Embossed Graphics','toys-hobbies','party-supplies','https://www.embossedgraphics.com/common/images/2015_item_images/801/c3001-801.jpg','["Family Personalized Candle - Engraved","24.95","USD","Embossed Graphics","Gifts","https://www.awin1.com/pclick.php?p=41721850485&a=2893129&m=117001","Make Every Moment Shine These candles are the perfect finishing touch, from intimate dinners to festive celebrations. So celebrate your family’s love and light up your space with something significant. After all, life’s too short for ordinary candles, right? Personalized your candle today • Personalization: Two lines of personalization (10 character/spaces per line) • Ink fill colors: 5 ink color options • Weight: 14 ounces • Includes gift box (standard)"]'),
('awin-embossed-graphics-family-personalized-soap-engraved-117001-41721851746','Embossed Graphics','toys-hobbies','party-supplies','https://www.embossedgraphics.com/common/images/2015_item_images/801/spd449-801.jpg','["Family Personalized Soap - Engraved","17.95","USD","Embossed Graphics","Gifts","https://www.awin1.com/pclick.php?p=41721851746&a=2893129&m=117001","The Family Personalized Soap - Engraved is a popular selection with its large two lines of personalization expertly engraved into our decorative bar of soap."]')
) AS src(slug, brand, department, product_type, image_url, payload)) AS parsed
ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name, price=EXCLUDED.price, currency=EXCLUDED.currency,
  brand=EXCLUDED.brand, merchant=EXCLUDED.merchant, category=EXCLUDED.category, department=EXCLUDED.department,
  product_type=EXCLUDED.product_type, image_url=EXCLUDED.image_url, affiliate_url=EXCLUDED.affiliate_url,
  description=EXCLUDED.description, source_data=EXCLUDED.source_data;
INSERT INTO awin_catalog_products
  (slug, name, price, currency, brand, merchant, category, department, product_type, image_url, affiliate_url, description, source_data)
SELECT slug, data->>'product_name', (data->>'search_price')::numeric, data->>'currency', brand,
  data->>'merchant_name', data->>'category_name', department, product_type, image_url,
  data->>'aw_deep_link', data->>'description', data
FROM (SELECT slug, brand, department, product_type, image_url,
  to_jsonb(jsonb_object(ARRAY['product_name','search_price','currency','merchant_name','category_name','aw_deep_link','description'], ARRAY(SELECT jsonb_array_elements_text(payload::jsonb)))) AS data FROM (VALUES
