('awin-fan-ink-club-america-onyx-trucker-103359-42123600196','Fan Ink','shoes-bags','fashion-accessories','https://cdn.shopify.com/s/files/1/1417/4238/products/CAM-2028-1426-1-min.png?v=1602621932','["Club America Onyx Trucker","31.99","USD","Fan Ink","Accessories","https://www.awin1.com/pclick.php?p=42123600196&a=2893129&m=103359","This Club America officially licensed diagonally checkered quilted front panels hat features team logo with a sonic weld patch on the front and a sonic weld suede wrap label on the back. The hat is made of 100% Polyester. Support your team in this 5-panel mid crown, curved peak snapback trucker hat!"]'),
('awin-fan-ink-club-america-orion-snapback-103359-42123600233','Fan Ink','shoes-bags','fashion-accessories','https://cdn.shopify.com/s/files/1/1417/4238/products/CAM-2093-5323-1-min.png?v=1602856005','["Club America Orion Snapback","35.99","USD","Fan Ink","Accessories","https://www.awin1.com/pclick.php?p=42123600233&a=2893129&m=103359","This Club America officially licensed hat features team logo 3D embroidery on front and embroidery on back. The hat is made of 55% cotton, 30% polyester, 15% PU and has a contrast PU peak and top button. Support your team in this 6-panel high crown, flat peak snapback hat!"]')
) AS src(slug, brand, department, product_type, image_url, payload)) AS parsed
ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name, price=EXCLUDED.price, currency=EXCLUDED.currency,
  brand=EXCLUDED.brand, merchant=EXCLUDED.merchant, category=EXCLUDED.category, department=EXCLUDED.department,
  product_type=EXCLUDED.product_type, image_url=EXCLUDED.image_url, affiliate_url=EXCLUDED.affiliate_url,
  description=EXCLUDED.description, source_data=EXCLUDED.source_data;
INSERT INTO awin_catalog_products
  (slug, name, price, currency, brand, merchant, category, department, product_type, image_url, affiliate_url, description, source_data)
SELECT slug, data->>'product_name', (data->>'search_price')::numeric, data->>'currency', brand,
  data->>'merchant_name', data->>'category_name', department, product_type, image_url,
  data->>'aw_deep_link', data->>'description', data
FROM (SELECT slug, brand, department, product_type, image_url,
  to_jsonb(jsonb_object(ARRAY['product_name','search_price','currency','merchant_name','category_name','aw_deep_link','description'], ARRAY(SELECT jsonb_array_elements_text(payload::jsonb)))) AS data FROM (VALUES
